//! Typed controls of the actual shared ownership kernels. Independent whole oracle is an example.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_raw_file::{self,Config},captured_raw_tree_pages::{Policy,Data},captured_raw_policy::Configuration,reactive_raw_policy_pages::RawPolicyPages};use std::{sync::Arc,path::Path,io};
#[path="../fixtures/native-ownership-workspace/fixture.rs"]mod fixture;
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>,visits:std::cell::Cell<usize>,stop:Option<usize>}
impl RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,captured_raw_file::RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{let phase=self.visits.get();self.visits.set(phase+1);for(relative,text)in &self.rows{if !captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(self.stop!=Some(phase))}}
fn actual<T>(value:Result<T,Failure>)->io::Error{match value{Err(Failure::Operational(e))=>e,Err(Failure::Unsupported(e))=>panic!("not actual operational error: {e}"),Ok(_)=>panic!("controlled operation completed")}}
fn run(text:String,limit:usize,poll:&dyn Fn()->io::Result<()>,stop:Option<usize>)->Result<Data,Failure>{let root=std::env::current_dir().unwrap().join("ownership-raw-controls");let budget=Budget::new(limit).map_err(|s|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,s)))?;let acquired=dm_preprocess::AcquiredSource::from_original_bytes(text.into_bytes(),());let pages=Pages{root:&root,rows:vec![("code/main.dm".into(),acquired.lease().source_text().clone())],budget:budget.clone(),visits:std::cell::Cell::new(0),stop};let cfg=Config::capture(Configuration::ProvenMissing).unwrap();let out=crate::captured_raw_tree_pages::collect(&pages,Policy::Ownership,&cfg,&budget,poll)?;assert_eq!(pages.visits.get(),3);Ok(out)}
#[test]fn actual_ownership_typed_inner_loops_preserve_1450_quota_cancel_and_recover(){let text=format!("/obj/holder\n    var/obj/child\n/obj/holder/proc/x()\n{}", "    own_set(src, nameof(missing), null)\n".repeat(2000));let count=std::cell::Cell::new(0usize);let poll=||{let n=count.get()+1;count.set(n);if n==1450{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};assert_eq!(actual(run(text.clone(),128*1024*1024,&poll,None)).raw_os_error(),Some(1450));assert_eq!(count.get(),1450);assert_eq!(actual(run(text.clone(),256,&||Ok(()),None)).kind(),io::ErrorKind::OutOfMemory);let cancelled=||Err(io::Error::from(io::ErrorKind::Interrupted));assert_eq!(actual(run(text.clone(),128*1024*1024,&cancelled,None)).kind(),io::ErrorKind::Interrupted);let recovered=run(text,128*1024*1024,&||Ok(()),None).unwrap();assert_eq!(recovered.sites().len(),2000);assert!(recovered.message_only());assert!(recovered.source_text().is_empty());}
#[test]fn ownership_all_three_actual_source_exhaustions_are_mandatory(){let text="/obj/holder/proc/x()\n    own_set(src, nameof(missing), null)\n";for phase in 0..3{assert!(matches!(run(text.into(),16*1024*1024,&||Ok(()),Some(phase)),Err(Failure::Unsupported(_))));}assert!(!run(text.into(),16*1024*1024,&||Ok(()),None).unwrap().sites().is_empty());}
#[test]fn ownership_raw_role_exact_metadata_and_phase_selection_never_claims_semantics(){let p=Policy::Ownership;assert_eq!(p.metadata().select.roots,crate::tree::CODE_DM.roots);assert!(!p.metadata().select.hidden);assert!(matches!(p.metadata().policy,crate::lint::Policy::Hard));assert_eq!(p.source_visits(),3);assert!(!p.selected_source_phase(0));assert!(!p.selected_source_phase(1));assert!(p.selected_source_phase(2));assert_eq!(Policy::from_name("ownership"),Some(p));for bad in["Ownership","ownership/other","stored_refs"]{assert_ne!(Policy::from_name(bad),Some(p));}}

#[test]fn ownership_large_generated_menu_and_member_index_fit_real_sixty_four_mib_not_per_line_taxes(){
 for case in ["large_menu","large_generated","large_members"]{let files=fixture::files(case);let text=files.iter().find(|(p,_)|*p=="code/main.dm").unwrap().1.clone();if case=="large_generated"{assert!(text.len()>=9_609_633);}if case=="large_menu"{assert!(text.len()>=1_550_277);}let out=run(text,64*1024*1024,&||Ok(()),None).unwrap();assert!(out.sites().is_empty(),"{case}: {:?}",out.sites());assert_eq!(out.notes(),&["ownership lint: 0 problems (clean)".to_string()]);}
}
#[test]fn ownership_one_line_actual_hit_suffix_overlap_is_prefunded_then_clean_retry_recovers(){
 let text=format!("/obj/holder\n    var/obj/child\n/obj/holder/proc/write()\n    {}\n","child = src; ".repeat(8192));let denied=actual(run(text,64*1024*1024,&||Ok(()),None));assert_eq!(denied.kind(),io::ErrorKind::OutOfMemory);
 let recovered=run("/obj/holder\n    var/obj/child\n/obj/holder/proc/write()\n    child = src\n".into(),64*1024*1024,&||Ok(()),None).unwrap();assert_eq!(recovered.sites().len(),1);assert_eq!(recovered.sites()[0].rule,"raw_write");
}
